// Profile real pointer drags on isolated copies of saved canvases. Build with --sourcemap for CPU attribution.
import assert from 'node:assert/strict';
import {mkdtemp,rm,readFile,writeFile,mkdir} from 'node:fs/promises';
import {tmpdir,homedir} from 'node:os';
import path from 'node:path';
import {spawn} from 'node:child_process';
import {createServer} from 'node:net';
import {seedMappingFixture} from '../browser/support/browser-mapping-fixture.mjs';
import {CanvasCatalogStore} from '../../infrastructure/core/persistence/canvasCatalogStore.ts';
import {WorkspaceRecordStore} from '../../infrastructure/mapping/persistence/workspace/workspaceRecordStore.ts';
import {documentFromHistory} from '../../domain/core/diagrams/canvasHistory.ts';
import {flattenGrid,resolveScene} from '../../domain/core/diagrams/lineGrid.ts';
import {initialCanvasState} from '../../domain/mapping/workspace/mappingWorkspace.ts';
const {withHeadlessBrowser,evaluate,waitFor,captureScreenshot}=await import(path.join(homedir(),'.codex/skills/front-end/browser-test.mjs'));
const source=process.env.DRAG_STORE;if(!source)throw Error('Set DRAG_STORE to the saved canvas directory');
const root=await mkdtemp(path.join(tmpdir(),'connected-drag-')),report=process.env.DRAG_REPORT??path.join(root,'report');
const ids=(process.env.DRAG_CANVASES??'').split(',');
assert.ok(ids.length===1&&ids[0], 'Set DRAG_CANVASES to one saved canvas ID per run');
let server;
try{
 await seedMappingFixture(root,{ascii:'Fixture',nodes:[]});await mkdir(report,{recursive:true});
 const project=JSON.parse(await readFile(path.join(source,'project.json'),'utf8'));
 const catalog=await new CanvasCatalogStore(source).loadCurrentRepresentationCatalog(project.id);
 const fixtureProject=JSON.parse(await readFile(path.join(root,'.diagrams/project.json'),'utf8'));
 const documents=ids.map((id,index)=>{const rep=catalog.representations[id],history=structuredClone(catalog.revisions[rep.currentRevisionId].content.history);for(const snapshot of Object.values(history.snapshots))if(snapshot.view)delete snapshot.view.viewport;const document=documentFromHistory(history);const boxes=flattenGrid(resolveScene(document.scene)).filter(b=>b.contentId);const box=boxes.find(b=>/Presentation alternatives|Placement alternatives|placement choice/i.test(document.scene.contents[b.contentId].content.ascii))??boxes[0];const viewport={scale:.5,offset:{x:850-(box.bounds.column*8.4+190)*.5,y:350-(box.bounds.row*18+64)*.5}};return{viewport,
  representationId:`draft-profile-${index}`,name:rep.name,savedName:rep.name,revisionId:rep.currentRevisionId,type:rep.type,document,history,canvas:history.snapshots[history.headId].view??initialCanvasState(),savedScene:JSON.stringify(document.scene),savedEdges:JSON.stringify(document.edges)
 };});
 await new WorkspaceRecordStore(path.join(root,'.diagrams')).state(fixtureProject.id,async()=>({schemaVersion:3,projectId:fixtureProject.id,activeDocumentId:"draft-profile-0",documents}));
 const port=await new Promise(resolve=>{const s=createServer();s.listen(0,'127.0.0.1',()=>{const p=s.address().port;s.close(()=>resolve(p));});});const url=`http://127.0.0.1:${port}`;
 server=spawn(process.execPath,['scripts/dev/start-server.mjs','preview','--host','127.0.0.1','--port',String(port),'--strictPort'],{env:{...process.env,NEW_DIAGRAM_PROJECT_ROOT:root,NEW_DIAGRAMS_DIR:path.join(root,'.diagrams'),NEW_DIAGRAM_AGENT:'fake'},stdio:'ignore'});
 await waitFor(async()=>(await fetch(url).catch(()=>null))?.ok,{timeoutMs:30000});
 const results=[];
 for(const [index,id] of ids.entries())await withHeadlessBrowser({url:`${url}/mapping?diagram=draft-profile-${index}`,width:1800,height:1100,chromePath:process.env.CHROME_PATH??path.join(homedir(),'.cache/ms-playwright/chromium-1228/chrome-linux64/chrome'),arguments:['--no-sandbox','--disable-gpu']},async({cdp})=>{
  await cdp.send('Runtime.enable');await cdp.send('Profiler.enable');await cdp.send('Page.enable');
  cdp.on('Page.javascriptDialogOpening',()=>void cdp.send('Page.handleJavaScriptDialog',{accept:true}));
  const errors=[];cdp.on('Runtime.exceptionThrown',e=>errors.push(e.exceptionDetails.text));
  const scope='.mapping-document-view:not([hidden]) ';
  await waitFor(async()=>await evaluate(cdp,`!!document.querySelector('${scope}[data-native-node^="grid:"] pre')`),{timeoutMs:60000});
  await evaluate(cdp,'document.fonts.ready.then(()=>true)');
  const mouse=params=>cdp.send('Input.dispatchMouseEvent',params);


  const target=await evaluate(cdp,`(()=>{const all=[...document.querySelectorAll('${scope}[data-native-node^="grid:"]')].filter(e=>e.querySelector('pre'));return (all.find(e=>/Presentation alternatives|Placement alternatives|placement choice/i.test(e.querySelector('pre').textContent))??all[1]??all[0]).dataset.nativeNode})()`);
  console.log(JSON.stringify({canvas:id,target}));
  if(documents[index].type==='generated') assert.ok(target.startsWith('grid:rollup-'),'Profile the generated diagram, not the seed canvas');
  const selector=scope+`[data-native-node="${target}"]`;
  const bounds=()=>evaluate(cdp,`document.querySelector('${selector}').getBoundingClientRect().toJSON()`);
  await evaluate(cdp,`new Promise(resolve=>{let last='',count=0;const tick=()=>{const r=document.querySelector('${selector}').getBoundingClientRect();const key=[r.x,r.y,r.width,r.height].join();count=key===last?count+1:0;last=key;if(count>=8)resolve(true);else requestAnimationFrame(tick)};tick()})`);
  const selected=await bounds(), corner={x:selected.right-2,y:selected.top+4};
  await mouse({type:'mousePressed',...corner,button:'left',buttons:1,clickCount:1});
  await mouse({type:'mouseReleased',...corner,button:'left',buttons:0,clickCount:1});
  await waitFor(async()=>await evaluate(cdp,`!!document.querySelector('${selector} [data-diagram-move-handle]')`));
  const trials=[];
  for(let trial=0;trial<2;trial++){
   const before=await bounds(), column=await evaluate(cdp,`document.querySelector('${selector} [data-grid-box]').dataset.gridColumn`);
   const origin=await evaluate(cdp,`(()=>{const r=document.querySelector('${selector} [data-diagram-move-handle]').getBoundingClientRect();return{x:r.x+r.width/2,y:r.y+r.height/2}})()`);
   await mouse({type:'mouseMoved',...origin});
   const hit=await evaluate(cdp, `document.elementFromPoint(${origin.x},${origin.y})?.closest('[data-diagram-move-handle]')?.dataset.diagramMoveHandle`);
   if(hit!==target){await captureScreenshot(cdp,{output:path.join(report,'blocked-handle.png')});console.log(await evaluate(cdp, `document.elementFromPoint(${origin.x},${origin.y})?.outerHTML.slice(0,600)`));}
   assert.equal(hit,target,`Move handle must be visible at ${JSON.stringify(origin)}`);

   await cdp.send('Profiler.start');
   await evaluate(cdp,`(()=>{const p=window.__dragPerf={frames:[],tasks:[],start:performance.now(),last:performance.now()};p.observer=new PerformanceObserver(l=>p.tasks.push(...l.getEntries().map(e=>e.duration)));p.observer.observe({type:'longtask'});const tick=t=>{p.frames.push(t-p.last);p.last=t;p.raf=requestAnimationFrame(tick)};p.raf=requestAnimationFrame(tick)})()`);
   await mouse({type:'mousePressed',...origin,button:'left',buttons:1,clickCount:1});
   const started=performance.now();const dispatch=[];
   for(let i=1;i<=24;i++){await new Promise(r=>setTimeout(r,Math.max(0,started+i*16.67-performance.now())));const t=performance.now();await mouse({type:'mouseMoved',x:origin.x+i*3,y:origin.y+i,button:'left',buttons:1});dispatch.push(performance.now()-t);}
   const held=await bounds();assert.ok(held.x-before.x>60,'Pointer drag must move the intended diagram');
   const duration=performance.now()-started;
   const release=performance.now();
   await mouse({type:'mouseReleased',x:origin.x+72,y:origin.y+24,button:'left',buttons:0,clickCount:1});
   await evaluate(cdp,'new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(()=>resolve(true))))');
   const releaseMs=performance.now()-release;
   const observation=await evaluate(cdp,`(()=>{const p=window.__dragPerf;cancelAnimationFrame(p.raf);p.observer.disconnect();return{frames:p.frames,tasks:p.tasks}})()`);
   const profile=(await cdp.send('Profiler.stop')).profile;await writeFile(path.join(report,`drag-${index}-${trial}.cpuprofile`),JSON.stringify(profile));
   const frames=observation.frames.slice(1).sort((a,b)=>a-b);
   const result={trial,durationMs:duration,releaseMs,p95:frames[Math.floor(frames.length*.95)],maxFrame:Math.max(...frames),maxDispatch:Math.max(...dispatch),longTasks:observation.tasks,frames:frames.length};trials.push(result);console.log(JSON.stringify({id,target,...result}));
   await waitFor(async()=>await evaluate(cdp,`document.querySelector('${selector} [data-grid-box]').dataset.gridColumn !== ${JSON.stringify(column)}`),{timeoutMs:15000});
   await writeFile(path.join(report,`results-${index}.json`),JSON.stringify({id,target,trials},null,2));
  }
  assert.ok(await evaluate(cdp, `performance.getEntriesByType('resource').some(entry=>entry.name.includes('routing.worker'))`), 'Background router must load');
  await captureScreenshot(cdp,{output:path.join(report,`canvas-${index}.png`)});assert.deepEqual(errors,[]);results.push({id,target,trials});
 });
 await writeFile(path.join(report,'results.json'),JSON.stringify(results,null,2));
}finally{if(server){const closed=new Promise(r=>server.once('exit',r));server.kill('SIGTERM');await closed;}await rm(root,{recursive:true,force:true});}
